#include "combined_pipeline.hpp"
#include <memory>
struct SubmissionResources;
struct PageResources {Image image{};VkDescriptorSet set{};int generation=0;bool live=false,canceled=false,uploadComplete=false;SubmissionResources* uploadSubmission=nullptr;};
struct SubmissionResources {VkCommandBuffer cb{};VkFence fence{};bool pending=false;Buffer staging{},vertices{},colorRead{},velocityRead{},idRead{};Image target{},velocity{},id{};VkFramebuffer fb{};};
struct Engine {
 TextLab& v;PageResources* published=nullptr;VkSemaphore gate{};uint64_t releaseGate=0;std::vector<std::unique_ptr<PageResources>> pages;std::vector<std::unique_ptr<SubmissionResources>> submissions;
 Engine(TextLab& lab):v(lab){VkSemaphoreTypeCreateInfo ti{VK_STRUCTURE_TYPE_SEMAPHORE_TYPE_CREATE_INFO};ti.semaphoreType=VK_SEMAPHORE_TYPE_TIMELINE;VkSemaphoreCreateInfo ci{VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO};ci.pNext=&ti;VK(vkCreateSemaphore(v.device,&ci,nullptr,&gate));}
 void freeImage(Image& i){vkDestroyImageView(v.device,i.view,nullptr);vkDestroyImage(v.device,i.image,nullptr);vkFreeMemory(v.device,i.memory,nullptr);i={};}
 void freeBuffer(Buffer& b){if(b.map)vkUnmapMemory(v.device,b.memory);vkDestroyBuffer(v.device,b.buffer,nullptr);vkFreeMemory(v.device,b.memory,nullptr);b={};}
 void wait(SubmissionResources& s){if(s.pending){VK(vkWaitForFences(v.device,1,&s.fence,VK_TRUE,10'000'000'000ull));s.pending=false;for(auto& p:pages)if(p->uploadSubmission==&s)p->uploadComplete=true;}}
 void signal(uint64_t n){VkSemaphoreSignalInfo si{VK_STRUCTURE_TYPE_SEMAPHORE_SIGNAL_INFO};si.semaphore=gate;si.value=n;VK(vkSignalSemaphore(v.device,&si));}
 unsigned livePages(){unsigned n=0;for(auto& p:pages)n+=p->live;return n;}
 int publishedGeneration(){return published?published->generation:-1;}
 void cancel(PageResources& p){if(!p.live||published==&p)throw std::runtime_error("invalid candidate cancel");p.canceled=true;}
 bool publish(PageResources& p){if(!p.live||p.canceled||!p.uploadComplete||(published&&p.generation<published->generation))return false;published=&p;return true;}
 SubmissionResources& drawPublished(const std::vector<float>& vertices,uint64_t gateValue=0){if(!published||!published->live||published->canceled)throw std::runtime_error("no valid published page");return draw(*published,vertices,gateValue);}
 void retire(PageResources& p){if(published==&p)throw std::runtime_error("retire published page");for(auto& s:submissions)if(s->pending)throw std::runtime_error("page retirement with pending consumers");if(p.live){VK(vkFreeDescriptorSets(v.device,v.textPool,1,&p.set));freeImage(p.image);p.live=false;}}
 PageResources& page(int gen){auto p=std::make_unique<PageResources>();p->generation=gen;p->image=v.image(VK_FORMAT_R32_SFLOAT,VK_IMAGE_USAGE_TRANSFER_DST_BIT|VK_IMAGE_USAGE_SAMPLED_BIT,VK_IMAGE_ASPECT_COLOR_BIT);VkDescriptorSetAllocateInfo ai{VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO};ai.descriptorPool=v.textPool;ai.descriptorSetCount=1;ai.pSetLayouts=&v.textSetLayout;VK(vkAllocateDescriptorSets(v.device,&ai,&p->set));VkDescriptorImageInfo ii{v.sampler,p->image.view,VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL};VkWriteDescriptorSet w{VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET};w.dstSet=p->set;w.descriptorCount=1;w.descriptorType=VK_DESCRIPTOR_TYPE_COMBINED_IMAGE_SAMPLER;w.pImageInfo=&ii;vkUpdateDescriptorSets(v.device,1,&w,0,nullptr);p->live=true;pages.push_back(std::move(p));return *pages.back();}
 SubmissionResources& begin(){auto s=std::make_unique<SubmissionResources>();VkCommandBufferAllocateInfo ai{VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};ai.commandPool=v.pool;ai.level=VK_COMMAND_BUFFER_LEVEL_PRIMARY;ai.commandBufferCount=1;VK(vkAllocateCommandBuffers(v.device,&ai,&s->cb));VkFenceCreateInfo fi{VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};VK(vkCreateFence(v.device,&fi,nullptr,&s->fence));VkCommandBufferBeginInfo bi{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};bi.flags=VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;VK(vkBeginCommandBuffer(s->cb,&bi));submissions.push_back(std::move(s));return *submissions.back();}
 void submit(SubmissionResources& s,uint64_t waitGate=0){VK(vkEndCommandBuffer(s.cb));VkSubmitInfo si{VK_STRUCTURE_TYPE_SUBMIT_INFO};si.commandBufferCount=1;si.pCommandBuffers=&s.cb;VkTimelineSemaphoreSubmitInfo ti{VK_STRUCTURE_TYPE_TIMELINE_SEMAPHORE_SUBMIT_INFO};VkPipelineStageFlags stage=VK_PIPELINE_STAGE_ALL_COMMANDS_BIT;if(waitGate){releaseGate=std::max(releaseGate,waitGate);ti.waitSemaphoreValueCount=1;ti.pWaitSemaphoreValues=&waitGate;si.pNext=&ti;si.waitSemaphoreCount=1;si.pWaitSemaphores=&gate;si.pWaitDstStageMask=&stage;}VK(vkQueueSubmit(v.queue,1,&si,s.fence));s.pending=true;}
 struct CmdScope{TextLab& v;VkCommandBuffer old;CmdScope(TextLab& v,VkCommandBuffer cb):v(v),old(v.cb){v.cb=cb;}~CmdScope(){v.cb=old;}};
 SubmissionResources& upload(PageResources& p,const std::vector<float>& mask){auto& s=begin();s.staging=v.buffer(mask.size()*4,VK_BUFFER_USAGE_TRANSFER_SRC_BIT);std::memcpy(s.staging.map,mask.data(),mask.size()*4);CmdScope scope(v,s.cb);v.barrier(VK_PIPELINE_STAGE_HOST_BIT,VK_ACCESS_HOST_WRITE_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_TRANSFER_READ_BIT);v.transition(p.image,VK_IMAGE_ASPECT_COLOR_BIT,VK_IMAGE_LAYOUT_UNDEFINED,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,0,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_TRANSFER_WRITE_BIT);VkBufferImageCopy cp{};cp.imageSubresource={VK_IMAGE_ASPECT_COLOR_BIT,0,0,1};cp.imageExtent={65,49,1};vkCmdCopyBufferToImage(s.cb,s.staging.buffer,p.image.image,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,1,&cp);v.transition(p.image,VK_IMAGE_ASPECT_COLOR_BIT,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_TRANSFER_WRITE_BIT,VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT,VK_ACCESS_SHADER_READ_BIT);submit(s);p.uploadSubmission=&s;return s;}
 SubmissionResources& draw(PageResources& p,const std::vector<float>& vertices,uint64_t gateValue=0){if(!p.live)throw std::runtime_error("dead page route");auto& s=begin();s.vertices=v.buffer(vertices.size()*4,VK_BUFFER_USAGE_VERTEX_BUFFER_BIT);std::memcpy(s.vertices.map,vertices.data(),vertices.size()*4);auto usage=VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT|VK_IMAGE_USAGE_TRANSFER_SRC_BIT|VK_IMAGE_USAGE_TRANSFER_DST_BIT;s.target=v.image(VK_FORMAT_R32G32B32A32_SFLOAT,usage,VK_IMAGE_ASPECT_COLOR_BIT);s.velocity=v.image(VK_FORMAT_R32G32B32A32_SFLOAT,usage,VK_IMAGE_ASPECT_COLOR_BIT);s.id=v.image(VK_FORMAT_R32G32B32A32_SFLOAT,usage,VK_IMAGE_ASPECT_COLOR_BIT);s.colorRead=v.buffer(65*49*16,VK_BUFFER_USAGE_TRANSFER_DST_BIT);s.velocityRead=v.buffer(65*49*16,VK_BUFFER_USAGE_TRANSFER_DST_BIT);s.idRead=v.buffer(65*49*16,VK_BUFFER_USAGE_TRANSFER_DST_BIT);VkImageView views[]={s.target.view,s.velocity.view,s.id.view};VkFramebufferCreateInfo fi{VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO};fi.renderPass=v.textPass;fi.attachmentCount=3;fi.pAttachments=views;fi.width=65;fi.height=49;fi.layers=1;VK(vkCreateFramebuffer(v.device,&fi,nullptr,&s.fb));CmdScope scope(v,s.cb);v.barrier(VK_PIPELINE_STAGE_HOST_BIT,VK_ACCESS_HOST_WRITE_BIT,VK_PIPELINE_STAGE_VERTEX_INPUT_BIT,VK_ACCESS_VERTEX_ATTRIBUTE_READ_BIT);
 Image images[]={s.target,s.velocity,s.id};float clear[3][4]={{.1f,.2f,.3f,.5f},{.125f,-.25f,.5f,1},{37,91,12,1}};VkImageSubresourceRange range{VK_IMAGE_ASPECT_COLOR_BIT,0,1,0,1};for(int i=0;i<3;i++){v.transition(images[i],VK_IMAGE_ASPECT_COLOR_BIT,VK_IMAGE_LAYOUT_UNDEFINED,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,VK_PIPELINE_STAGE_TOP_OF_PIPE_BIT,0,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_TRANSFER_WRITE_BIT);VkClearColorValue c{};std::memcpy(c.float32,clear[i],16);vkCmdClearColorImage(s.cb,images[i].image,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,&c,1,&range);v.transition(images[i],VK_IMAGE_ASPECT_COLOR_BIT,VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL,VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_TRANSFER_WRITE_BIT,VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,VK_ACCESS_COLOR_ATTACHMENT_READ_BIT|VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT);}
 VkRenderPassBeginInfo ri{VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO};ri.renderPass=v.textPass;ri.framebuffer=s.fb;ri.renderArea={{0,0},{65,49}};vkCmdBeginRenderPass(s.cb,&ri,VK_SUBPASS_CONTENTS_INLINE);vkCmdBindPipeline(s.cb,VK_PIPELINE_BIND_POINT_GRAPHICS,v.textPipeline);vkCmdBindDescriptorSets(s.cb,VK_PIPELINE_BIND_POINT_GRAPHICS,v.textLayout,0,1,&p.set,0,nullptr);float ink[]={.9f,.5f,.2f,.75f};vkCmdPushConstants(s.cb,v.textLayout,VK_SHADER_STAGE_FRAGMENT_BIT,0,16,ink);VkDeviceSize offset=0;vkCmdBindVertexBuffers(s.cb,0,1,&s.vertices.buffer,&offset);vkCmdDraw(s.cb,vertices.size()/4,1,0,0);vkCmdEndRenderPass(s.cb);Buffer targets[]={s.colorRead,s.velocityRead,s.idRead};for(int i=0;i<3;i++){v.transition(images[i],VK_IMAGE_ASPECT_COLOR_BIT,VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL,VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL,VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT|VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT|VK_ACCESS_TRANSFER_WRITE_BIT,VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_TRANSFER_READ_BIT);v.copyImage(images[i],VK_IMAGE_ASPECT_COLOR_BIT,targets[i]);}v.barrier(VK_PIPELINE_STAGE_TRANSFER_BIT,VK_ACCESS_TRANSFER_WRITE_BIT,VK_PIPELINE_STAGE_HOST_BIT,VK_ACCESS_HOST_READ_BIT);submit(s,gateValue);return s;}
 ~Engine(){uint64_t current=0;vkGetSemaphoreCounterValue(v.device,gate,&current);if(current<releaseGate){VkSemaphoreSignalInfo si{VK_STRUCTURE_TYPE_SEMAPHORE_SIGNAL_INFO};si.semaphore=gate;si.value=releaseGate;if(vkSignalSemaphore(v.device,&si)!=VK_SUCCESS)std::_Exit(2);}try{for(auto& s:submissions)wait(*s);}catch(...){std::cerr<<"COMBINED_CLEANUP_TIMEOUT"<<std::endl;std::_Exit(2);}for(auto& s:submissions){if(s->fb)vkDestroyFramebuffer(v.device,s->fb,nullptr);freeImage(s->target);freeImage(s->velocity);freeImage(s->id);freeBuffer(s->staging);freeBuffer(s->vertices);freeBuffer(s->colorRead);freeBuffer(s->velocityRead);freeBuffer(s->idRead);vkDestroyFence(v.device,s->fence,nullptr);vkFreeCommandBuffers(v.device,v.pool,1,&s->cb);}published=nullptr;for(auto& p:pages)retire(*p);vkDestroySemaphore(v.device,gate,nullptr);if(validationErrors){std::cerr<<"COMBINED_CLEANUP_VALIDATION_FAILURE"<<std::endl;std::_Exit(2);}std::cout<<"COMBINED_PENDING_CLEANUP_OK\n";}
};
static std::vector<float> read(const char* p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()<=0||f.tellg()%4||f.tellg()>65536)throw std::runtime_error("input size");std::vector<float>a(size_t(f.tellg())/4);f.seekg(0);f.read(reinterpret_cast<char*>(a.data()),a.size()*4);for(float x:a)if(!std::isfinite(x))throw std::runtime_error("nonfinite");return a;}
static void dump(SubmissionResources& s,const std::filesystem::path& folder){std::filesystem::create_directory(folder);for(auto entry:{std::pair<const char*,Buffer*>{"color.rgba32f",&s.colorRead},{"velocity.rgba32f",&s.velocityRead},{"id.rgba32f",&s.idRead}}){std::ofstream f(folder/entry.first,std::ios::binary);f.write(reinterpret_cast<char*>(entry.second->map),65*49*16);}}
int main(int argc,char**argv){try{if(argc!=5&&argc!=6)throw std::runtime_error("usage combined SHADERS ATLAS VERTICES NEW_OUT [--abort-pending]");if(argc==6&&std::string(argv[5])!="--abort-pending")throw std::runtime_error("bad mode");auto mask=read(argv[2]),verts=read(argv[3]);if(mask.size()!=3185||verts.size()!=72)throw std::runtime_error("controlled fixture dimensions");for(float x:mask)if(x<0||x>1)throw std::runtime_error("mask range");for(size_t i=0;i<verts.size();i+=4)if(std::abs(verts[i])>4||std::abs(verts[i+1])>4||verts[i+2]<0||verts[i+2]>1||verts[i+3]<0||verts[i+3]>1)throw std::runtime_error("vertex bounds");std::filesystem::path out=argv[4];if(!std::filesystem::create_directory(out))throw std::runtime_error("existing output");
 {TextLab v(argv[1]);Engine e(v); // discard unused inherited coverage; actual pages are independently owned
 e.freeImage(v.coverage);auto& a=e.page(0);auto& ua=e.upload(a,mask);e.wait(ua);if(!e.publish(a))throw std::runtime_error("initial publish failed");auto& old=e.drawPublished(verts,1);auto& b=e.page(1);auto cancelMask=mask;for(auto& x:cancelMask)x*=.25f;auto& ub=e.upload(b,cancelMask);if(e.publish(b))throw std::runtime_error("pending upload published");e.cancel(b);if(e.publish(b))throw std::runtime_error("canceled upload published");
 if(vkGetFenceStatus(v.device,old.fence)!=VK_NOT_READY||vkGetFenceStatus(v.device,ub.fence)!=VK_NOT_READY)throw std::runtime_error("gated work not pending");for(PageResources* page:{&a,&b}){bool rejected=false;try{e.retire(*page);}catch(const std::runtime_error&){rejected=true;}if(!rejected)throw std::runtime_error("pending page retirement allowed");}std::ofstream events(out/"events.jsonl");events<<"{\"phase\":\"cancel_B_pending\",\"published\":"<<e.publishedGeneration()<<",\"A_pending\":true,\"B_upload_pending\":true,\"live_pages\":"<<e.livePages()<<"}\n";
 if(argc==6)throw std::runtime_error("INTENTIONAL_COMBINED_PENDING_CLEANUP");e.signal(1);e.wait(old);e.wait(ub);dump(old,out/"old-A");
 if(e.publish(b))throw std::runtime_error("completed canceled page published");auto& route=e.drawPublished(verts);e.wait(route);dump(route,out/"route-after-cancel");auto& wrong=e.draw(b,verts);e.wait(wrong);dump(wrong,out/"wrong-cancel-route");e.retire(b);events<<"{\"phase\":\"cancel_B_retired\",\"published\":"<<e.publishedGeneration()<<",\"live_pages\":"<<e.livePages()<<"}\n";
 auto& newer=e.page(2);auto nextMask=mask;for(auto& x:nextMask)x*=.5f;auto& un=e.upload(newer,nextMask);e.wait(un);if(!e.publish(newer))throw std::runtime_error("new publish failed");if(e.publish(a))throw std::runtime_error("publication rollback allowed");auto& next=e.drawPublished(verts,2);if(vkGetFenceStatus(v.device,next.fence)!=VK_NOT_READY)throw std::runtime_error("new draw not pending");events<<"{\"phase\":\"new_B_published_pending\",\"published\":"<<e.publishedGeneration()<<",\"live_pages\":"<<e.livePages()<<"}\n";e.signal(2);e.wait(next);dump(next,out/"new-B");e.retire(a);events<<"{\"phase\":\"old_A_retired\",\"published\":"<<e.publishedGeneration()<<",\"live_pages\":"<<e.livePages()<<"}\n";std::cout<<"COMBINED_PASS validation_enabled="<<v.validation<<"\n";
 }if(validationErrors)throw std::runtime_error("validation errors");std::cout<<"COMBINED_RESOURCES_DESTROYED\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return validationErrors?2:1;}}
